<?php
require dirname(__DIR__).'/dashboard/private/state.php';
function check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$s=initial_state();$job=add_job($s,['docket'=>'25-735','argument_date'=>'2026-10-05','audio_url'=>'https://www.supremecourt.gov/a.mp3','pdf_url'=>'https://www.supremecourt.gov/t.pdf']);$id=$job['id'];command($s,['command'=>'start','job'=>$id]);foreach(['prepare','enrich','align','plan','render'] as $k)$s['jobs'][$id]['stages'][$k]['status']='complete';
$dispatch=worker_update($s,['op'=>'dispatch','job'=>$id,'stage'=>'assemble'],'dispatcher');$base=['job'=>$id,'stage'=>'assemble','dispatch_token'=>$dispatch['dispatch_token']];$claim=worker_update($s,['op'=>'claim',...$base],'assemble');
$finish=['op'=>'finish',...$base,'lease'=>$claim['lease'],'result'=>['video_uri'=>'gs://bucket/video.mp4','sha256'=>'saved'],'continue_upload'=>true,'handoff_id'=>str_repeat('a',32)];
$next=worker_update($s,$finish,'assemble');check($s['jobs'][$id]['stages']['assemble']['status']==='complete','Assembly checkpoint missing');check($next['next']['job']['stages']['upload']['status']==='starting','Upload not reserved atomically');
$again=worker_update($s,$finish,'assemble');check($again['next']['dispatch_token']===$next['next']['dispatch_token']&&$s['jobs'][$id]['stages']['upload']['attempt']===1,'Lost finish reply caused duplicate upload');
check(worker_update($s,['op'=>'dispatch','job'=>$id,'stage'=>'upload'],'dispatcher')===null,'Controller launched second upload');
$operation='projects/project/locations/us-central1/operations/owned';worker_update($s,['op'=>'execution_record',...$base,'operation'=>$operation],'dispatcher');check($s['jobs'][$id]['stages']['upload']['cloud_operation']===$operation,'Late operation receipt did not follow handoff');
$upload=['job'=>$id,'stage'=>'upload','dispatch_token'=>$next['next']['dispatch_token']];$owned=worker_update($s,['op'=>'claim',...$upload],'upload');worker_update($s,['op'=>'checkpoint',...$upload,'lease'=>$owned['lease'],'checkpoint'=>['video_id'=>'existing']],'upload');worker_update($s,['op'=>'fail',...$upload,'lease'=>$owned['lease'],'error'=>'worker_failed'],'upload');check($s['jobs'][$id]['stages']['assemble']['result']['sha256']==='saved','Upload failure lost assembly');check($s['jobs'][$id]['stages']['upload']['checkpoint']['video_id']==='existing','Upload failure lost saved video');check($s['jobs'][$id]['stages']['upload']['status']==='failed','Wrong failure phase');
echo "Delivery handoff checks passed: atomic reservation, reply retry, checkpoint reuse and failure attribution.\n";
